package snmp
import("bufio";"encoding/csv";"errors";"os";"path/filepath";"strconv";"strings")
func CorpusRejectionsLocal(root,list,output string)error{ in,e:=os.Open(list);if e!=nil{return e};defer in.Close();recs,e:=csv.NewReader(in).ReadAll();if e!=nil{return e};out,e:=os.Create(output);if e!=nil{return e};defer out.Close();w:=csv.NewWriter(out);defer w.Flush();w.Write([]string{"path","line","reason","declared_type"});for _,rec:=range recs[1:]{p:=rec[0];f,e:=os.Open(filepath.Join(root,p));if e!=nil{return e};b:=bufio.NewReader(f);recording:=contentIsSnmprec(b);s:=bufio.NewScanner(b);s.Buffer(make([]byte,65536),8<<20);lineNo:=0;lastHex:=false;for s.Scan(){lineNo++;raw:=s.Text();line:=strings.TrimSpace(raw);if line==""||strings.HasPrefix(line,"#")||isEndOfMIBLine(line){continue};if !recording&&lastHex&&isHexContinuation(line){continue};var entry *WalkEntry;var err error;if recording{entry,err=parseSnmprecLine(raw)}else{entry,err=parseWalkLine(line)};if err==nil{lastHex=isHexStringLine(line);_ =entry;continue};reason:="other_parser_error";for _,item:=range []struct{err error;name string}{{ErrSymbolicOID,"unresolved_symbolic_oid"},{ErrInvalidOIDComponent,"invalid_numeric_oid"},{ErrInvalidWalkFormat,"invalid_walk_format"},{ErrMissingColon,"missing_type_colon"},{ErrInvalidTimeticksFormat,"invalid_timeticks_format"}}{if errors.Is(err,item.err){reason=item.name;break}};var num *strconv.NumError;if errors.As(err,&num){if errors.Is(num.Err,strconv.ErrRange){reason="numeric_out_of_range"}else{reason="invalid_numeric_syntax"}};kind:="";if recording{parts:=strings.SplitN(raw,"|",3);if len(parts)>1{kind=parts[1]}}else{_,rhs,_:=strings.Cut(line,"=");kind,_,_=strings.Cut(rhs,":");kind=strings.TrimSpace(kind)};if len(kind)>40{kind="unrecognized"};w.Write([]string{p,strconv.Itoa(lineNo),reason,kind})};if e=s.Err();e!=nil{return e};f.Close()};w.Flush();return w.Error()}
